'use strict';
/**
 * STAMP WHAT THE COMMITTED BUNDLE WAS BUILT FROM.
 *
 * Run automatically by `npm run build` in app-v2/ (see its package.json). It
 * writes `web/v2/portal/.bundle-manifest.json`: a hash of every source file the
 * bundle is built from, plus the hashed asset names the build produced.
 *
 * `scripts/check-bundle-fresh.js` recomputes the source hash and compares. That
 * pair is what makes the browser drive mean anything — see that file's header
 * for why.
 */

const fs = require('fs');
const path = require('path');
const crypto = require('crypto');
const { sourceHash, PORTAL, MANIFEST } = require('./lib/bundle-hash');

const root = path.join(__dirname, '..');
const assets = fs.existsSync(path.join(root, PORTAL, 'assets'))
  ? fs.readdirSync(path.join(root, PORTAL, 'assets')).sort()
  : [];
const indexHtml = fs.readFileSync(path.join(root, PORTAL, 'index.html'), 'utf8');

const manifest = {
  note: 'Generated by app-v2\'s build. Do not hand-edit — run `npm run build` in app-v2/ and commit web/v2/portal/.',
  sourceHash: sourceHash(root),
  assets,
  indexHash: crypto.createHash('sha256').update(indexHtml).digest('hex').slice(0, 16),
  builtAt: new Date().toISOString(),
};
fs.writeFileSync(path.join(root, PORTAL, '.bundle-manifest.json'), `${JSON.stringify(manifest, null, 2)}\n`);
console.log(`[bundle-manifest] source ${manifest.sourceHash} -> ${assets.length} asset(s)`);
